/**
 * Bundle build: concatenate the client sections into the single module the
 * browser loader expects. Run `node build.mjs` after editing src/sections/.
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'

const here = new URL('./', import.meta.url)
const sectionsDir = new URL('./src/sections/', here)
const sections = readdirSync(sectionsDir).filter((name) => name.endsWith('.js')).sort()

const header = `/**
 * Off-peak — browser half. Generated by build.mjs from src/sections/; edit those
 * files, not this one.
 */
window.__ModuleLoader__.load({
  id: 'dsh-plugin-offpeak',
  factory(require) {
    const React = require('react')
    const h = React.createElement
`

const footer = `  },
})
`

const body = sections.map((name) => {
  const source = readFileSync(new URL(name, sectionsDir), 'utf8')
  return `\n/* ============================ ${name} ============================ */\n${source}`
}).join('\n')

writeFileSync(new URL('./client.js', here), header + body + footer)
console.log(`client.js written from ${sections.length} sections`)
